```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved extension: record the input in the shared store.
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        let body = http_client::get(&feed_url);
        let fetched = body.chars().count() as u32;

        let notified = notifier::notify(&format!(
            "heartbeat at {}: fetched {} chars from {}",
            seconds, fetched, feed_url
        ));
        // Contract: `notified == true` must hold of every output.
        assert!(notified, "notification was not accepted");

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
